export function SessionParticipant({screenMode=false}:{screenMode?:boolean}){
 const[deliveryNote,setDeliveryNote]=useState('');
 const[editingTicket,setEditingTicket]=useState(false);
 const[confidence,setConfidence]=useState(2),[reflection,setReflection]=useState(''),[help,setHelp]=useState('');
 const[code,setCode]=useState(''),[nickname,setNickname]=useState(''),[token,setToken]=useState(''),[sessionId,setSessionId]=useState(''),[view,setView]=useState<View|null>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false);
 useEffect(()=>{let active=true;void Promise.resolve().then(()=>{if(!active)return;const invited=new URLSearchParams(window.location.search).get('code');if(invited&&/^[A-Fa-f0-9]{10}$/.test(invited)){setCode(invited.toUpperCase());if(!screenMode){try{if(sessionStorage.getItem('hc-participant-code')!==invited.toUpperCase()){sessionStorage.removeItem('hc-participant');return;}}catch{return;}}}if(screenMode){const [id,t]=window.location.hash.slice(1).split(':');setSessionId(id||'');setToken(t||'')}else{try{setToken(sessionStorage.getItem('hc-participant')||'')}catch{}}});return()=>{active=false}},[screenMode]);
 const remaining=useRemaining(view);
 const refresh=useCallback(async()=>{if(!token)return;try{let result=await api<View>('?view='+(screenMode?'screen&id='+encodeURIComponent(sessionId):'student'),undefined,token);let retryMessage='';if(!screenMode){let pending:null|{token:string;question:string;choice:number}=null;try{pending=JSON.parse(sessionStorage.getItem('hc-pending-answer')||'null')}catch{}if(pending?.token===token){try{result=await api<View>('',{action:'answer',...pending});sessionStorage.removeItem('hc-pending-answer')}catch(e){if(e instanceof ApiError&&e.status>=400&&e.status<500&&e.status!==429){sessionStorage.removeItem('hc-pending-answer');retryMessage='Your answer could not reach the teacher before the question closed.'}else throw e}}}setView(result);if(retryMessage)setDeliveryNote(retryMessage);setError('')}catch(e){setError(e instanceof ApiError?message(e):'Connection interrupted. Reconnecting… Your saved answers are safe.');if(e instanceof ApiError&&e.status===401){setToken('');try{sessionStorage.removeItem('hc-participant')}catch{}}}},[token,screenMode,sessionId]);
 useEffect(()=>{if(!token)return;let inFlight=false;const tick=()=>{if(document.hidden||inFlight)return;inFlight=true;void refresh().finally(()=>{inFlight=false})};tick();const t=setInterval(tick,3000);window.addEventListener('online',tick);window.addEventListener('pageshow',tick);document.addEventListener('visibilitychange',tick);return()=>{clearInterval(t);window.removeEventListener('online',tick);window.removeEventListener('pageshow',tick);document.removeEventListener('visibilitychange',tick)}},[refresh,token]);
 async function join(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');try{const normalized=code.replace(/\s/g,'').toUpperCase();const key='hc-join:'+normalized;let recoveryToken=sessionStorage.getItem(key);if(!recoveryToken){recoveryToken=Array.from(crypto.getRandomValues(new Uint8Array(32)),b=>b.toString(16).padStart(2,'0')).join('');sessionStorage.setItem(key,recoveryToken)}const d=await api<{token:string}>('',{action:'join',code:normalized,nickname,recoveryToken});try{sessionStorage.setItem('hc-participant',d.token);sessionStorage.setItem('hc-participant-code',code.replace(/\s/g,'').toUpperCase())}catch{}setToken(d.token)}catch(e){setError(e instanceof ApiError?message(e):'Connection interrupted. Tap Join again to recover your place.')} finally{setBusy(false)}}
 async function submitExit(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');try{setView(await api<View>('',{action:'exit-ticket',token,confidence,reflection,help}));setEditingTicket(false)}catch(e){setError(message(e))}finally{setBusy(false)}}
 async function answer(i:number){if(!view?.question)return;setBusy(true);setError('');setDeliveryNote('');const pending={token,question:view.question.id,choice:i};try{const existing=sessionStorage.getItem('hc-pending-answer');if(existing&&JSON.parse(existing).token===token){setError('Your previous answer is waiting to reconnect.');return;}sessionStorage.setItem('hc-pending-answer',JSON.stringify(pending));try{setView(await api<View>('',{action:'answer',...pending}));sessionStorage.removeItem('hc-pending-answer')}catch(e){if(e instanceof ApiError&&e.status>=400&&e.status<500&&e.status!==429){sessionStorage.removeItem('hc-pending-answer');setError(message(e))}else setError('Answer saved on this device. Sending when the connection returns…')}}catch{setError('This browser cannot keep your answer safely. Enable browser storage before answering.')}finally{setBusy(false)}}
 return <main className={`${s.page} ${screenMode?s.presentation:''} ${token&&view?s.playSpace:''}`}>{!screenMode&&!view&&<Header/>}{deliveryNote&&<p role="status" className={s.error}>{deliveryNote}</p>}{error&&<p role="alert" className={s.error}>{error}</p>}{!token?<section className={s.onboard}><div><p className={s.eyebrow}>FREE / FOR STUDENTS</p><h1>{screenMode?'Your classroom screen':'You’re part of the class.'}</h1>{screenMode?<p>Open this screen from your teacher workspace.</p>:<form onSubmit={join}><p>Get the code from your teacher. No account needed.</p><label>Session code<input value={code} onChange={e=>setCode(e.target.value.toUpperCase())} maxLength={10} required autoComplete="off" placeholder="10-character code"/></label><label>Your nickname or initials<input value={nickname} onChange={e=>setNickname(e.target.value)} maxLength={30} required autoComplete="off" placeholder="e.g. Alex M."/></label><button className={s.primary} disabled={busy}>{busy?'Joining…':'Join session →'}</button><p className={s.hint}>Your nickname appears on the classroom screen and may appear on the leaderboard. Responses are kept for up to seven days. Don’t enter your full name or email. <a href="/privacy">Privacy</a></p></form>}</div><Art name="join" alt="Illustrated learners joining a classroom with a phone"/></section>:!view?<p role="status">Joining your classroom…</p>:<section className={s.live}><div className={`${s.sectionHead} ${s.playBar}`}><a className={s.playLogo} href="/headcount" aria-label="Headcount home">✳ <strong>Headcount<span>.</span></strong></a><div className={s.playerIdentity}><p className={s.eyebrow}>{view.name}</p><span>{screenMode?'CLASSROOM SCREEN':view.nickname}</span></div><div>{screenMode&&<><SessionSound view={view}/><FullscreenButton/></>}<span className={s.badge}>{view.joined} joined</span></div></div>
 {view.phase==='countdown'?<Countdown view={view}/>:screenMode&&view.boardEnabled?<div className={s.projectedBoard}><Leaderboard view={view}/></div>:view.phase==='lobby'&&screenMode?<ScreenLobby view={view}/>:view.phase==='lobby'?<div className={s.lobby}><div className={s.waitingMascot} aria-hidden="true">✦</div><h1>{screenMode?'Ready, class?':'You’re on the team.'}</h1><p>{screenMode?'Join at starkfiber.my/headcount/join':'Your teacher will start the first question.'}</p><strong className={s.bigCode}>{view.code}</strong>{screenMode&&<JoinQr code={view.code}/>}{screenMode&&<div className={s.stats}>{Object.entries(view.attendance).map(([k,v])=><div key={k}><strong>{v}</strong><span>{k}</span></div>)}</div>}</div>:view.phase==='exit'?<div className={s.exitPanel}><p className={s.eyebrow}>BEFORE YOU GO</p><h1>One last little check-in.</h1>{screenMode?<><p>On your device: share one thing you learned and anything you want help with.</p><Art name="results" alt="Classroom learning illustration"/></>:view.exitTicket&&!editingTicket?<div role="status"><h2>Your teacher has your ticket.</h2><p>Thanks for sharing. Your response stays private to your teacher.</p><button onClick={()=>{setConfidence(view.exitTicket!.confidence);setReflection(view.exitTicket!.reflection);setHelp(view.exitTicket!.help);setEditingTicket(true)}}>Edit my ticket</button></div>:<form onSubmit={submitExit}><label>How confident do you feel?<select value={confidence} onChange={e=>setConfidence(Number(e.target.value))}><option value={1}>I need help</option><option value={2}>I’m getting there</option><option value={3}>I can explain it</option></select></label><label>One thing I learned <span>Optional</span><textarea maxLength={280} value={reflection} onChange={e=>setReflection(e.target.value)}/></label><label>I would like help with <span>Optional</span><textarea maxLength={280} value={help} onChange={e=>setHelp(e.target.value)}/></label><p className={s.hint}>Only your teacher sees this. Keep it about the lesson; don’t include personal or sensitive details.</p><button className={s.primary} disabled={busy}>{busy?'Sending…':'Send my exit ticket →'}</button></form>}</div>:view.phase==='ended'?<div className={s.lobby}><Art name="results" alt="Illustrated celebration of classroom progress"/><p className={s.eyebrow}>SESSION COMPLETE</p><h1>That’s a wrap!</h1>{!screenMode&&<p className={s.score}>{view.score} correct / {view.total} questions</p>}{!screenMode&&<Celebration view={view}/>}<p>Keep the conversation going. What did you learn?</p>{!screenMode&&<button onClick={()=>{try{sessionStorage.removeItem('hc-participant')}catch{}setToken('');setView(null)}}>Join another session</button>}</div>:view.question&&<div className={s.round} key={view.question.id}><div className={s.roundMeta}><span className={s.questionNumber}>Question <b>{view.current+1}</b><span> / {view.total}</span></span><Clock view={view}/><span className={s.answerCount}>{view.answered} / {view.joined} answered</span></div><progress aria-label="Quiz progress" max={view.total} value={view.current+1}/><div className={s.questionStage}><span className={s.stageStar} aria-hidden="true">✦</span><h1>{view.question.text}</h1><p>{view.phase==='reveal'?'Let’s see how you did.':screenMode?'Make your choice on your device.':'Trust your thinking. Pick one.'}</p></div><div className={s.answers} data-long={view.question.options.some(option=>option.length>60)} data-answered={!screenMode&&view.choice!==null} data-revealed={view.phase==='reveal'}>{view.question.options.map((text,i)=><button key={i} aria-pressed={!screenMode&&view.choice===i} className={view.phase==='reveal'&&view.question?.correct===i?s.correct:''} disabled={screenMode||busy||view.phase!=='question'||view.choice!==null||remaining===0} onClick={()=>void answer(i)}><span className={s.answerLetter}>{'ABCD'[i]}</span><strong className={s.answerText}>{text}</strong>{!screenMode&&view.choice===i&&<small className={s.picked}>Your pick</small>}{view.phase==='reveal'&&view.question?.correct===i&&<b>✓</b>}</button>)}</div>{!screenMode&&view.phase==='reveal'&&<Celebration view={view}/>}<p role="status" className={s.roundStatus}>{view.phase==='reveal'?'Answer revealed':!screenMode&&view.choice!==null?'✓ Answer locked in — watch the classroom screen.':remaining===0?'Time’s up. Your teacher will reveal the answer.':screenMode?'Waiting for the class…':'Tap your answer to lock it in.'}</p>{view.phase==='reveal'&&screenMode&&<div className={s.distribution}>{view.question.distribution?.map((n,i)=><div key={i}><span>{'ABCD'[i]}</span><div className={s.resultTrack} role="meter" aria-label={'Option '+'ABCD'[i]} aria-valuemin={0} aria-valuemax={Math.max(1,view.answered)} aria-valuenow={n}><i style={{width:(n/Math.max(1,view.answered)*100)+'%'}}/></div><strong>{n}</strong></div>)}</div>}<p className={s.hint}>{view.answered} answers received{!screenMode&&view.phase==='reveal'?' · Your score: '+view.score:''}</p></div>}
 {!screenMode&&<Leaderboard view={view}/>}</section>}</main>;
}
